package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoMontageReviewTest {
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun montageActivity():HonorableVideoEditorActivity=activity().also{a->val p=VideoEditProject(60000);val clips=(0 until 3).map{i->VideoSegment(i*20000L,(i+1)*20000L,title="Scene ${i+1}",captions=listOf(VideoCaption(i*20000L+9000,i*20000L+11000,"Cue ${i+1}")),captionSourceUri="content://synthetic/subtitles-$i")};p.restore(clips,soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(a,"project",p);set(a,"primaryDurationMs",60000L);set(a,"durationMs",60000)}
 private fun prepared(a:HonorableVideoEditorActivity,target:Long=15000):Pair<VideoBatchReview,AlertDialog>{val p=get(a,"project")as VideoEditProject;val r=VideoBatchReview(p.segments,p.soundtrack);val d=dialog();r.open(d);r.propose(d,VideoStoryTools.montage(p.segments,target));set(a,"batchReviewRequest",r);set(a,"batchReviewDialog",d);set(a,"captionReviewDialogs",linkedSetOf(d));return r to d}
 private fun commit(a:HonorableVideoEditorActivity,pair:Pair<VideoBatchReview,AlertDialog>,r:VideoCaptionReviewState)=call(a,"commitBatchReview",pair.second,pair.first,r)as Boolean
 @Test fun pausedMontageEntryReturnsBeforeAnyChooser(){val a=montageActivity();set(a,"workspaceActive",false);call(a,"montageOptions");assertNull(get(a,"batchReviewRequest"));assertNull(get(a,"batchReviewDialog"))}
 @Test fun currentMontageAppliesBalancedExcerptsAndOneUndoKeepsMusicProvenance(){val a=montageActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val music=p.soundtrack;val r=capture(a);val pair=prepared(a);assertTrue(commit(a,pair,r));assertEquals(15000L,p.totalDurationMs);assertEquals(listOf(7500L,27500L,47500L),p.segments.map{it.startMs});assertEquals(old.map{it.title},p.segments.map{it.title});assertEquals(old.map{it.captionSourceUri},p.segments.map{it.captionSourceUri});assertEquals(old.map{it.captions},p.segments.map{it.captions});assertSame(music,p.soundtrack);assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());assertEquals(15000L,p.totalDurationMs)}
 @Test fun chooserLateDismissDoesNotCancelSuccessorReview(){val a=montageActivity();val p=get(a,"project")as VideoEditProject;val r=capture(a);val pair=prepared(a);val confirmation=dialog();pair.first.open(confirmation);pair.first.propose(confirmation,VideoStoryTools.montage(p.segments,15000));set(a,"batchReviewDialog",confirmation);set(a,"captionReviewDialogs",linkedSetOf(confirmation));pair.first.dismiss(pair.second);assertFalse(pair.first.isClosed);assertFalse(commit(a,pair,r));assertFalse(pair.first.isClosed);assertTrue(commit(a,pair.first to confirmation,r))}
 @Test fun cancelledOrDismissedMontageReviewCannotApply(){for(decor in listOf(false,true)){val a=montageActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val r=capture(a);val pair=prepared(a);if(decor)showing(pair.second,false)else set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());assertFalse(commit(a,pair,r));assertSame(old,p.segments);assertFalse(p.canUndo);assertTrue(pair.first.isClosed)}}
 @Test fun montageRequiresCurrentSessionGenerationSourceRangeMusicAndRecovery(){for(flag in listOf("pause","generation","source","duration","range","music","mode","recovery","busy")){val a=montageActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val r=capture(a);val pair=prepared(a);when(flag){"pause"->set(a,"workspaceActive",false);"generation"->set(a,"captionReviewGeneration",r.generation+1);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",60001L);"range"->set(a,"selectedClip",1);"music"->p.setSoundtrack(p.soundtrack!!.copy(volume=.5f));"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));else->set(a,"saving",true)};assertFalse(flag,commit(a,pair,r));assertSame(old,p.segments);assertTrue(pair.first.isClosed)}}
 @Test fun duplicateOrUndoRevivedApprovalCannotApplyAgain(){val a=montageActivity();val p=get(a,"project")as VideoEditProject;val r=capture(a);val pair=prepared(a);assertTrue(commit(a,pair,r));assertFalse(commit(a,pair,r));assertTrue(p.undo());assertEquals(true,call(a,"canApplyCaptionReview",r));assertFalse(commit(a,pair,r));assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun existingTargetsAndShortFootageBehaviorRemain(){val a=montageActivity();val p=get(a,"project")as VideoEditProject;for(target in listOf(15000L,30000L,60000L)){val result=VideoStoryTools.montage(p.segments,target);assertEquals(target*1000,result.sumOf{it.durationUs});assertEquals(3,result.size);assertEquals(p.segments.map{it.title},result.map{it.title})};val short=listOf(VideoSegment(0,3000));assertEquals(short,VideoStoryTools.montage(short,15000));assertEquals(p.segments,VideoStoryTools.montage(p.segments,60000));assertFalse(p.canUndo)}
 @Test fun montageDraftRecoveryKeepsExcerptsCaptionsSourceReferencesAndMusic(){val a=montageActivity();val p=get(a,"project")as VideoEditProject;val r=capture(a);val pair=prepared(a);assertTrue(commit(a,pair,r));val clip=p.segments[0];val draft=VideoDraft(60000,p.segments,0,clip.startMs,clip.startMs,clip.endMs,soundtrack=p.soundtrack);val restored=requireNotNull(VideoDraftCodec.decode(VideoDraftCodec.encode(draft),60000));assertEquals(draft,restored);assertEquals(3,VideoCaptions.resolve(restored.segments).size);assertEquals(3,restored.segments.mapNotNull{it.captionSourceUri}.distinct().size)}
}
